  ["shared.previewsamples.see_the_wanted_popup_portrait_nearby_highlight.04e33a"] = "檢視想要的彈出視窗, 肖像, 附近的亮點和名牌硬幣. 重播使用您的聲音偏好設定。",
  ["shared.previewsamples.portraits_use_your_selected_player_or_your.6ec2ed"] = "肖像使用您選擇的玩家或您的角色作為標籤示例。 這永遠不會給他們帶來好處。 實時警報來自觀察,包括目標、滑鼠懸停和名牌。",
  ["shared.previewsamples.wanted_board.b69f07"] = "慾望板",
  ["shared.previewsamples.wanted_cards_and_full_posters.c0244c"] = "想要的卡片和完整的海報",
  ["shared.previewsamples.click_the_wanted_card_or_view_bounty.b1ae32"] = "點選想要的卡片或檢視獎勵,以檢查每個貢獻者,他們的條款,資金和到期。 重新整理 在樣品獎勵到達時顯示禁用的按鈕和載入程式。",
  ["shared.previewsamples.start_tracking_adds_a_target_to_my.e9b443"] = "開始跟蹤 將目標新增到我的獎勵中。 檢測到殺傷後,檢視報告 將開啟其狀態。 海報將目標和獎勵放在第一位,使用羊皮紙寬度的細節,並在需要時滾動。 無法獲得的肖像被標記。",
  ["shared.previewsamples.create_terms.1ea507"] = "建立條款",
  ["shared.previewsamples.build_a_sample_bounty.01af6d"] = "構建樣本懸賞",
  ["shared.previewsamples.three_steps_target_reward_review_nothing_is.cc55e8"] = "三個步驟:目標、獎勵、評估。 在最終確認之前不會儲存任何內容。 一個殺死任何結束是預設值。",
  ["shared.previewsamples.save_returns_to_the_tour_sharing_is.631c62"] = "儲存返回到旅行。 共享是可選的。 私人追蹤可以使用零黃金;共享獎勵需要正值和過期。 首選的完成需要海報的審查。 沒有生存獎勵被建立。",
  ["shared.previewsamples.use_gold_across_your_characters.423446"] = "將黃金用於您的角色",
  ["shared.previewsamples.see_a_sample_wallet_and_the_bag.2652f4"] = "檢視示例錢包和袋子黃金工具提示。 嘗試兩個開關,然後在\"建立 & 條款\"中輸入大於可用金額的獎勵。",
  ["shared.previewsamples.account_tracking_is_on_by_default_requiring.faa230"] = "預設情況下,帳戶跟蹤處於開啟狀態。 要求足夠的黃金預設是關閉的:超預算獎勵警告,但可以建立。 餘額範圍為此領域或永恆領域集。 Alt 餘額在您登入時更新;支付和轉賬仍然是手動的。",
  ["shared.previewsamples.guild_approval.d5172b"] = "行會批准",
  ["shared.previewsamples.submit_and_approve_a_guild_bounty.93c32d"] = "提交併批准公會懸賞",
  ["shared.previewsamples.try_awaiting_approval_officer_approval_and_rejection.1aed32"] = "嘗試等待批准, 官員批准和拒絕, 然後檢查由此產生的通緝卡. 即使沒有公會,這些角色也可以在遊覽中使用。",
  ["shared.previewsamples.approved_guild_rewards_can_show_a_new.36cbe4"] = "經批准的公會獎勵可以顯示新獎勵海報。 這是宣佈獎勵,而不是觀察。 與公會和全球董事會共享獎勵不會產生第二次付款義務。 在 Forever 上,社群獎勵僅與您規則集的成員同步。",
  ["shared.previewsamples.shared_arrivals.7e4e7c"] = "共同抵達",
  ["shared.previewsamples.a_bounty_matches_your_filters.542556"] = "懸賞符合您的篩選條件",
  ["shared.previewsamples.use_start_tracking_or_ignore_on_the.ac8ad1"] = "在傳入的海報上使用開始跟蹤 或忽略 。 嘗試示例警報設定和供資狀態。 這一目標尚未被發現。",
  ["shared.previewsamples.the_notification_minimum_counts_rewards_with_current.7ea6f7"] = "通知最低數量計算獎勵與當前可用資金報告。 進口的、過時的或沒有資金的報價仍然可以區分。 追蹤不會帶來金錢;忽略會讓目標的懸賞和目擊警報沉默。",
  ["shared.previewsamples.grow_a_bounty_s_pot.fc063b"] = "生長一個懸賞的鍋",
  ["shared.previewsamples.add_a_sample_contribution_review_the_original.3e1e7c"] = "新增樣本貢獻,檢視原始帖子的條件,並檢視合併獎勵更新。",
  ["shared.previewsamples.accepting_the_terms_means_the_original_poster.cb648e"] = "接受條款意味著原發布者決定索賠是否符合資格。 貢獻者應向同一被接受的獵人支付其金額。 黃金不會由附加元件持有或轉移。",
  ["shared.previewsamples.share_import.d10b63"] = "分享&匯入",
  ["shared.previewsamples.copy_a_bounty_link_and_review_an.e6954f"] = "複製懸賞連結並審查匯入",
  ["shared.previewsamples.sharing_outside_the_addon_is_optional_copy.b960a6"] = "在外掛之外共享是可選的。 複製全域性、公會或私人懸賞連結,然後檢視示例匯入。",
  ["shared.previewsamples.choose_select_link_to_copy_press_ctrl.75c0bf"] = "選擇\"選擇要複製的連結 \" , 按 Ctrl+C 併傳送懸賞連結。 收件人選擇匯入懸賞。 在聊天中分享可用於私人和群組懸賞。 Discord 通道單獨開啟共享板目標。 旅遊連結故意在旅遊之外無效。",
  ["shared.previewsamples.kills_reports.48e18a"] = "殺戮與報告",
  ["shared.previewsamples.detected_kills_create_reports_automatically.0ec7e1"] = "自動建立報告",
  ["shared.previewsamples.use_view_sample_report_to_follow_review.4dce46"] = "使用檢視示例報告 跟蹤審查。 嘗試重複殺戮和截圖成功,失敗或重試。 影印證明是可選的。",
  ["shared.previewsamples.readable_killing_blows_are_confirmed_locally_named.83de2e"] = "當地確認了可讀的致命擊打。 指定榮譽積分可能包括助攻。 螢幕截圖核取方塊確認僅儲存了影象。 獎勵批准和支付仍然是分開的;手動報告是為了錯過的檢測。 這次旅行不需要螢幕截圖。",
  ["shared.previewsamples.follow_reports_through_review_and_payment.7bf30e"] = "透過稽核和付款跟蹤報告",
  ["shared.previewsamples.browse_hunter_and_poster_examples_awaiting_review.ee1784"] = "瀏覽獵人和海報示例:等待稽核,批准,付款和拒絕。 試試批准、拒絕和標記已付款作為示例海報。",
  ["shared.previewsamples.hunters_cannot_approve_their_own_reports_the.8e822e"] = "獵人不能批准自己的報告。 海報審查證據,並透過遊戲手動支付,然後記錄該付款。 重複殺戮可以計入多次殺戮目標,而無需為同一獎勵支付兩次費用。",
  ["shared.previewsamples.review_enemies_suggested_by_death_reports.470074"] = "審查死亡報告建議的敵人",
  ["shared.previewsamples.inspect_sample_reports_review_a_prefilled_bounty.a7057d"] = "檢查樣本報告,檢視預填報酬,駁回建議或忽略敵人。",
  ["shared.previewsamples.suggestions_combine_your_deaths_and_participating_guild.4596f6"] = "建議將您的死亡和參與公會報告合併到配置視窗中。 它們是要審查的線索,而不是伺服器驗證的殺死證明。 在您選擇受眾並儲存之前,不會發布任何內容。",
